WHERE EXISTS (SELECT 1 FROM bank_deposits d WHERE d.id = v.dep_id)
  AND NOT EXISTS (SELECT 1 FROM bank_deposit_components b WHERE b.bank_deposit_id = v.dep_id)
ON CONFLICT (bank_deposit_id) DO NOTHING;

-- Post-condition: every targeted deposit is now excluded (or component-backed).
DO $$
DECLARE missing int;
BEGIN
  SELECT count(*) INTO missing
  FROM bank_deposits d
  WHERE d.memo ILIKE '%1330 lag%'
    AND NOT EXISTS (SELECT 1 FROM bank_deposit_exclusions e WHERE e.bank_deposit_id = d.id)
    AND NOT EXISTS (SELECT 1 FROM bank_deposit_components b WHERE b.bank_deposit_id = d.id);
  IF missing > 0 THEN
    RAISE EXCEPTION '0207: % "1330 Lag" deposits still unexcluded and componentless', missing;
  END IF;
END $$;
